    public void handleTicker(Client client, Object message)
    {
        //
        // market/snapshot
        //
        // updates come in every 2 sec unless there
        // were no changes since the previous update
        //
        //     {
        //         "data": {
        //             "sequence": "1545896669291",
        //             "data": {
        //                 "trading": true,
        //                 "symbol": "KCS-BTC",
        //                 "buy": 0.00011,
        //                 "sell": 0.00012,
        //                 "sort": 100,
        //                 "volValue": 3.13851792584, // total
        //                 "baseCurrency": "KCS",
        //                 "market": "BTC",
        //                 "quoteCurrency": "BTC",
        //                 "symbolCode": "KCS-BTC",
        //                 "datetime": 1548388122031,
        //                 "high": 0.00013,
        //                 "vol": 27514.34842,
        //                 "low": 0.0001,
        //                 "changePrice": -1.0e-5,
        //                 "changeRate": -0.0769,
        //                 "lastTradedPrice": 0.00012,
        //                 "board": 0,
        //                 "mark": 0
        //             }
        //         },
        //         "subject": "trade.snapshot",
        //         "topic": "/market/snapshot:KCS-BTC",
        //         "type": "message"
        //     }
        //
        // market/ticker
        //
        //     {
        //         "type": "message",
        //         "topic": "/market/ticker:BTC-USDT",
        //         "subject": "trade.ticker",
        //         "data": {
        //             "bestAsk": "62163",
        //             "bestAskSize": "0.99011388",
        //             "bestBid": "62162.9",
        //             "bestBidSize": "0.04794181",
        //             "price": "62162.9",
        //             "sequence": "1621383371852",
        //             "size": "0.00832274",
        //             "time": 1634641987564
        //         }
        //     }
        //
        // futures
        //    {
        //     "subject": "ticker",
        //     "topic": "/contractMarket/ticker:XBTUSDM",
        //     "data": {
        //         "symbol": "XBTUSDM", //Market of the symbol
        //         "sequence": 45, //Sequence number which is used to judge the continuity of the pushed messages
        //         "side": "sell", //Transaction side of the last traded taker order
        //         "price": "3600.0", //Filled price
        //         "size": 16, //Filled quantity
        //         "tradeId": "5c9dcf4170744d6f5a3d32fb", //Order ID
        //         "bestBidSize": 795, //Best bid size
        //         "bestBidPrice": "3200.0", //Best bid
        //         "bestAskPrice": "3600.0", //Best ask size
        //         "bestAskSize": 284, //Best ask
        //         "ts": 1553846081210004941 //Filled time - nanosecond
        //     }
        //    }
        //
        String topic = this.safeString(message, "topic");
        if (((String)topic).indexOf("contractMarket") < 0)
        {
            Object market = null;
            if (!java.util.Objects.equals(topic, null))
            {
                Object parts = new ArrayList<Object>(Arrays.asList(((String)topic).split(java.util.regex.Pattern.quote(":"))));
                String first = this.safeString(parts, 1);
                String marketId = null;
                if (java.util.Objects.equals(first, "all"))
                {
                    marketId = this.safeString(message, "subject");
                } else
                {
                    marketId = first;
                }
                market = this.safeMarket(marketId, market, "-");
            }
            Map<String, Object> data = (Map<String, Object>) this.safeDict(message, "data", new HashMap<String, Object>() {{}});
            Object rawTicker = this.safeDict(data, "data", data);
            Object ticker = this.parseSpotOrUtaTicker(rawTicker, market);
            Object symbol = ((Map<String, Object>)ticker).get("symbol");
            Helpers.addElementToObject(this.tickers, ((String)symbol), ticker);
            String messageHash = Helpers.add("ticker:", symbol);
            client.resolve(ticker, messageHash);
            // watchTickers
            Map<String, Object> allTickers = new HashMap<String, Object>() {{}};
            ((Map<String, Object>)allTickers).put((String)((String)symbol), ticker);
            client.resolve(allTickers, "tickers");
        } else
        {
            this.handleContractTicker(client, message);
        }
    }

